### ขั้นตอนที่ 3: การรั่วไหลของน้ำในโบ๊ตล์
ตรวจสอบใช้งานเวลาเพื่อควบคุมการรั่วไหลของน้ำในโบ๊ตล์.

```csharp
using UnityEngine;
using UnityEngine.UI;

public class TimeBottle : MonoBehaviour
{
    public TimeBottlesManager manager;
    public Image waterFillImage;

    private float fillSpeed = 0.005f;
    private float fillAmount = 0f;

    private void Start()
    {
        waterFillImage.fillAmount = fillAmount;
    }

    private void Update()
    {
        // Assume time increment simulation
        fillAmount += fillSpeed * Time.deltaTime;
        waterFillImage.fillAmount = fillAmount;

        if (waterFillImage.fillAmount >= 1f)
        {
            waterFillImage.fillAmount = 1f;
            if (Input.GetKeyDown(KeyCode.E)) // Sample input check
            {
                OpenBottle();
            }
        }
    }

    private void OpenBottle()
    {
        SelectAndGoToScene();
    }

    private void SelectAndGoToScene()
    {
        // Implement UI to allow user selection or automatically choose
        if (manager != null && manager.timeBottles.Count > 0)
        {
            for (int i = 0; i < manager.timeBottles.Count; i++)
            {
                if (!string.IsNullOrEmpty(manager.timeBottles[i].sceneName))
                {
                    SceneController.Instance.ChangeScene(manager.timeBottles[i].sceneName, manager.timeBottles[i].sceneTime);
                    break;
                }
            }
        }
    }
}
```

